from common import *

def main():
 pairs=read(REPAIR/'data/D2/public/pairs.json');states=read(REPAIR/'data/D2/public/states.json');out=read(REPAIR/'data/D2/_private/outcomes.json')
 rules=[('A','open','blue','reference','success','开抽屉'),('B','lift','pink','reference','success','抓取粉块'),('C','place','red','held_open','success','正常放置红块'),('D','place','blue','held_closed','refused','关闭抽屉时尝试放置蓝块')]
 protocol={'created_utc':now(),'purpose':'Four sealed action cases: no training, no new physics, no threshold or test score changes.','model':'canonical_matched_seed0 selected update1000','selection':'Fixed categories in order open-blue/reference/success, lift-pink/reference/success, place-red/held_open/success, place-blue/held_closed/refused. Within each choose lexicographically smallest (root_id,pair_id) not previously used. Fixed target colours promote diversity. No selection by latent errors, query agreement, coordinates or visual appearance.','background':'All 338 frozen selected actual boundary states from latent_tsne_20261016; no new sampling.','union':'Concatenate 338 background vectors and 4 cases x current/predicted/actual. Alias an actual endpoint to existing background state ID when present; deduplicate exact vector duplicates with shared coordinates. Keep full logical-to-unique map. No jitter or point relocation.','scaling':'Reuse frozen 256D interaction AB-training mean/std from previous tSNE (102 AB points). No case or test data changes scaling.','projection':{'PCA':50,'PCA_solver':'full','fit':'once on full unique unlabeled union','n_components':2,'perplexity':30,'random_state':42,'init':'pca','learning_rate':'auto','early_exaggeration':12,'max_iter':1500,'method':'barnes_hut','angle':.5,'metric':'euclidean','n_jobs':1},'error':'mean over256 dimensions of ((prediction-actual)/frozen_AB_std)^2, unitless AB-standardized latent squared distance. Supplement raw latent MSE for crosscheck only.','render':'All four panels share one fitted coordinate system and exact axis ranges. Blue circle current, orange triangle prediction, green star actual; dashed orange prediction arrow and solid green actual arrow. Labels may use leader lines, coordinates never shifted.','ground_truth':'Only selecting user-requested outcome strata, semantic annotations and posthoc diagnostics. Never model, scaling, PCA or tSNE input.','refusal':'Executed place request was refused before controls; settling frames still recorded. Do not describe as mechanical movement failure.'}
 save(E/'configs/protocol.json',protocol)
 selected=[];used=set()
 for cid,fam,col,condition,status,title in rules:
  eligible=[p for p in pairs if p['skill'].split('_')[0]==fam and out[p['id']].get('target')==col and out[p['id']].get('condition')==condition and out[p['id']]['status']==status and p['root_id']not in used]
  assert eligible,(cid,fam,col);p=sorted(eligible,key=lambda p:(p['root_id'],p['id']))[0];used.add(p['root_id']);r=dict(p)|{'case_id':cid,'title':title,'colour':col,'condition':condition,'status':status,'candidate_pair_ids':[x['id']for x in sorted(eligible,key=lambda p:(p['root_id'],p['id']))]}
  for role in ['before','after']:
   st=states[p[role]];path=Path(st['path']);bounds=read(path.parent.parent/'_private/boundaries.json');b=next(b for b in bounds if b['name']==path.stem);r[role+'_path']=str(path);r[role+'_frame']=b['frame'];r[role+'_state_id']=st['id'];r[role+'_sha256']=sha(path)
  calls=read(Path(r['before_path']).parent.parent/'_private/calls.json');call=next(c for c in calls if c['role']=='task'and c['start_frame']==r['before_frame']and c['end_frame']==r['after_frame']);assert call['action']==r['action'];r['actual_executor_arguments']=call['executor_arguments'];r['native_reason']=call['native'].get('reason');r['actual_controls']=call['native'].get('controls');selected.append(r)
 save(E/'data/cases.json',selected)
 inputs=[PREV/'data/main_states.json',PREV/'data/main_latents.npz',PREV/'results/coordinates.npz',PREV/'configs/delivery_manifest.json',REPAIR/'data/D2/public/pairs.json',REPAIR/'data/D2/public/states.json',REPAIR/'data/D2/public/inputs.npz',REPAIR/'data/D2/_private/outcomes.json',REPAIR/'results/D2_canonical_matched_seed0.npz',REPAIR/'results/D2_records.json',REPAIR/'models/canonical_matched_seed0/selected.json',REPAIR/'data/public/normalization.npz',OLD/'models/interaction_seed0/selected.json']
 for rr in selected:
  for role in ['before','after']:inputs.append(Path(rr[role+'_path']))
 save(E/'configs/sources.json',{'sha256':{str(p):sha(p)for p in inputs}})
 print(json.dumps([{k:r[k]for k in['case_id','id','root_id','skill','before','after','before_frame','after_frame','status']}for r in selected],ensure_ascii=False))
if __name__=='__main__':main()
